WITH scored AS (SELECT *, AVG(cost) OVER (PARTITION BY carrier) AS carrier_avg_cost, LAST_VALUE(cost, TRUE) OVER (ORDER BY delivered_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_cost FROM shipments WHERE YEAR(shipped_date) >= 2024) SELECT DATE_TRUNC('YEAR', delivered_date) AS year_start, CASE WHEN carrier_avg_cost >= 83 THEN 'PREMIUM' ELSE 'STANDARD' END AS carrier_avg_cost_tier, COUNT(CASE WHEN status = 'LOST' THEN 1 END) AS lost_count, COUNT(DISTINCT status) AS distinct_status, STDDEV_SAMP(cost) AS cost_stddev FROM scored GROUP BY DATE_TRUNC('YEAR', delivered_date), CASE WHEN carrier_avg_cost >= 83 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY carrier_avg_cost_tier ASC
